package ch.jalu.configme.configurationdata;

import org.junit.Test;
import static org.junit.Assert.*;
import java.util.HashMap;
import java.util.Map;
import java.util.Collections;
import java.util.Arrays;

public class CommentsConfigurationTest {

    @Test
    public void newCommentsConfiguration_isEmpty() {
        CommentsConfiguration config = new CommentsConfiguration();
        assertEquals(0, config.getAllComments().size());
    }

    @Test
    public void newCommentsConfiguration_hasNoLines() {
        CommentsConfiguration config = new CommentsConfiguration(new HashMap<>());
        Map<String, List<String>> comments = config.getAllComments();
        assertTrue(comments.isEmpty());
    }

    @Test
    public void newCommentsConfiguration_hasSingleLineComment() {
        CommentsConfiguration config = new CommentsConfiguration(new HashMap<>());
        config.setComment("path", "\n# comment");
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(1, comments.size());
        assertTrue(comments.get("path").contains("# comment"));
    }

    @Test
    public void newCommentsConfiguration_hasMultipleLineComments() {
        CommentsConfiguration config = new CommentsConfiguration(new HashMap<>());
        config.setComment("path", "# comment1\n# comment2");
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(1, comments.size());
        assertTrue(comments.get("path").contains("# comment1"));
        assertTrue(comments.get("path").contains("# comment2"));
    }

    @Test
    public void newCommentsConfiguration_setComment_withExistingPath() {
        CommentsConfiguration config = new CommentsConfiguration(new HashMap<>());
        config.setComment("path", "# comment");
        config.setComment("path", "# newcomment");
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(1, comments.size());
        assertTrue(comments.get("path").contains("# newcomment"));
    }

    @Test
    public void newCommentsConfiguration_setComment_withEmptyLine() {
        CommentsConfiguration config = new CommentsConfiguration(new HashMap<>());
        config.setComment("path", "\n# comment");
        Map<String, List<String>> comments = config.getAllComments();
        assertEquals(1, comments.size());
        assertTrue(comments.get("path").contains("# comment"));
    }
}
